PIL.fr=[['Les décisions d’aujourd’hui ont besoin du contexte d’hier.','Consultez la presse depuis 1998, le web depuis 2004 et l’audiovisuel depuis 2006, à tout moment et sans demande préalable.'],['Ce que d’autres plateformes manquent, nous le captons.','Chaque journal de la première à la dernière page, chaque minute de diffusion, les médias internationaux en 131 langues, et toute source que vous demandez.'],['Une IA qui comprend l’arabe. Des analystes qui comprennent la région.','Une IA conçue pour l’arabe et ses dialectes, et plus de 100 analystes et chercheurs.'],['Vos données, là où vous le souhaitez.','Un déploiement sur site, avec un support humain 24 h/24 et 7 j/7.']];
PIL.tr=[['Bugünün kararları dünün bağlamına ihtiyaç duyar.','Basılı yayında 1998’den, web sitelerinde 2004’ten, yayınlarda 2006’dan bu yana istediğiniz an, önceden talep gerekmeden arama yapın.'],['Diğer platformların kaçırdığını biz kayda alırız.','Baştan sona her gazete, her yayın dakikası, 131 dilde küresel medya ve talep ettiğiniz her kaynak.'],['Arapçayı anlayan yapay zekâ. Bölgeyi anlayan analistler.','Arapça ve lehçeleri için geliştirilmiş yapay zekâ ve 100’ü aşkın analist ve araştırmacı.'],['Verileriniz, istediğiniz yerde.','Kurum içi (on-premises) kurulum ve 7/24 insan desteği.']];
PIL.ur=[['آج کے فیصلوں کو کل کا سیاق و سباق درکار ہے۔','1998 سے اخبارات، 2004 سے ویب سائٹس اور 2006 سے نشریات میں، کسی بھی وقت اور پیشگی درخواست کے بغیر تلاش کریں۔'],['جو دوسرے پلیٹ فارمز سے رہ جاتا ہے، ہم اسے محفوظ کرتے ہیں۔','ہر اخبار پہلے سے آخری صفحے تک، نشریات کا ہر منٹ، 131 زبانوں میں عالمی میڈیا، اور ہر وہ ماخذ جو آپ طلب کریں۔'],['عربی سمجھنے والی مصنوعی ذہانت۔ خطے کو سمجھنے والے تجزیہ کار۔','عربی اور اس کی بولیوں کے لیے تیار کی گئی مصنوعی ذہانت، اور 100 سے زائد تجزیہ کار اور محققین۔'],['آپ کا ڈیٹا، جہاں آپ چاہیں۔','آپ کے اپنے مقام پر (آن پریمیسس) تنصیب، اور چوبیس گھنٹے انسانی معاونت۔']];

